fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0L) return "0s"
    val seconds = exposureTimeNs / 1_000_000_000.0
    return if (seconds >= 0.5) {
        val rounded = Math.round(seconds * 10.0) / 10.0
        if (rounded % 1.0 == 0.0) "${rounded.toInt()}s" else "${rounded}s"
    } else {
        val denominator = (1.0 / seconds).roundToInt().coerceAtLeast(1)
        "1/${denominator}s"
    }
}

